pub fn close_wheel(&mut self) {
    if let Some(w) = self.wheel.take() {
        let c = match w.key.as_str() {
            "sel.fill" => [self.prefs.sel_fill[0], self.prefs.sel_fill[1], self.prefs.sel_fill[2]],
