        };
        self.prefs.recent_colors.retain(|x| (x[0] - c[0]).abs() + (x[1] - c[1]).abs() + (x[2] - c[2]).abs() > 0.004);
        self.prefs.recent_colors.insert(0, c);
        self.prefs.recent_colors.truncate(12);
        self.prefs.save();
    }
}

